    const size = value.length; let head;
    if (size <= 15) head = Buffer.from([0x90 | size]);
    else if (size <= 0xffff) { head = Buffer.allocUnsafe(3); head[0] = 0xdc; head.writeUInt16BE(size, 1); }
    else { head = Buffer.allocUnsafe(5); head[0] = 0xdd; head.writeUInt32BE(size, 1); }
