function pcProgress(pc,master) {
  const original = master?.pcProfiles?.[pc?.pcId];
  if (!original || !Array.isArray(original.jobIds) || !Number.isSafeInteger(pc.currentJobIndex) ||
      pc.currentJobIndex < 1 || pc.currentJobIndex > original.jobIds.length ||
      !Number.isSafeInteger(pc.totalExp) || pc.totalExp < 0 || !Number.isSafeInteger(pc.limitbreakCount) ||
      pc.limitbreakCount < 0 || pc.limitbreakCount > 5) return null;
  //22d10b0/22da418/22dfe60: original ordered jobs and growth group, not the
  // incidental job-set row order or a client-supplied displayed level.
  const jobRank = master.pcJobRanks?.[original.jobIds[pc.currentJobIndex-1]];
  const maximum = master.pcJobMaxLevels?.[jobRank]+pc.limitbreakCount*4;
  const level = master.pcLevels?.[original.levelUpType]?.findLast(([level,exp])=>level<=maximum && exp<=pc.totalExp)?.[0];
  return [jobRank,level].every(n=>Number.isSafeInteger(n) && n>0 && n<=0x7fffffff) ? { jobRank,level } : null;
}

const PC_STAT_KINDS = [1,2,4,8,16,32,64,128];
const DISPATCH_STAT_KINDS = [1,64,2,4,8,32,16];
const int32 = n => Number.isSafeInteger(n) && n >= -0x80000000 && n <= 0x7fffffff;
const pcStatVector = value => sameKeys(value,PC_STAT_KINDS.map(String)) && Object.values(value).every(int32);
const equipmentSlot = (slot,type) => Number.isSafeInteger(slot) &&
  (type===1 ? slot>=1 && slot<=500 : type===2 && slot>=10001 && slot<=10500);
