function captureLocalPvpParty(read,master,selection) {
  const infos=read('UserInfo').data,parties=read('UserPvPParty').data,
    saved=read('UserParty').data,owned=read('UserPC').data;
  if(![infos,parties,saved,owned].every(Array.isArray))
    fail(503,'Saved competitive profile vectors require reconciliation');
  const selected=saved.filter(row=>row?.id===infos[0]?.[selection]),party=parties[0],active=selected[0];
  if(infos.length!==1 || infos[0]?.userId!==USER_ID || parties.length!==1 ||
      !Number.isSafeInteger(infos[0][selection]) || infos[0][selection]<=0 ||
      !sameKeys(party,['userId','slots','attackPattern','memoriaSlots']) || party.userId!==USER_ID ||
      !int32(party.attackPattern) || party.attackPattern<0 || selected.length!==1 || active.userId!==USER_ID ||
      !Array.isArray(party.slots) || party.slots.length!==6 || !Array.isArray(active.slots) || active.slots.length!==6 ||
      !Array.isArray(party.memoriaSlots) || !Array.isArray(active.memoriaSlots) || active.memoriaSlots.length!==3 ||
      active.attackPattern!==party.attackPattern ||
      [party.slots,active.slots,party.memoriaSlots,active.memoriaSlots].some(rows=>
        !rows.every(row=>row && typeof row==='object' && !Array.isArray(row))))
    fail(503,'Current native competitive party snapshot unavailable; save retained');
  for(const slot of party.slots) {
    const matches=active.slots.filter(row=>row.slotNumber===slot.slotNumber);
    if((!sameKeys(slot,['slotNumber','pc','assistingPc','isHidden']) &&
        !sameKeys(slot,['slotNumber','pc','assistingPc','isHidden','commandFlow'])) ||
        matches.length!==1 || typeof slot.isHidden!=='boolean' ||
        Object.hasOwn(slot,'commandFlow') && typeof slot.commandFlow!=='string')
      fail(503,'Saved competitive party slot requires reconciliation');
    for(const [key,idKey] of [['pc','pcId'],['assistingPc','assistingPcId']]) {
      const pcId=slot[key]?.pcId,found=owned.filter(row=>row?.pcId===pcId);
      if(pcId!==matches[0][idKey] || pcId && (found.length!==1 || found[0].userId!==USER_ID || found[0].joiningState!==1))
        fail(503,'Saved competitive snapshot does not match the selected owned party');
    }
  }
  for(const slot of party.memoriaSlots) {
    const matches=active.memoriaSlots.filter(row=>row.slotNumber===slot.slotNumber);
    if(matches.length!==1 || slot.otherMemoria?.memoriaId!==matches[0].memoriaId)
      fail(503,'Saved competitive memoria snapshot does not match the selected party');
  }
  if(active.memoriaSlots.some(slot=>slot.memoriaId && !party.memoriaSlots.some(row=>row.slotNumber===slot.slotNumber)))
    fail(503,'Saved competitive memoria snapshot is incomplete');
  try {
    validatePvbParty({userId:USER_ID,slots:party.slots.map(({slotNumber,pc,assistingPc})=>({slotNumber,pc,assistingPc})),
      memoriaSlots:party.memoriaSlots},master);
  } catch { fail(503,'Saved native competitive party vector requires reconciliation'); }
  return party;
}

