  requireValue(bonuses.length > 0, 'Missing original PvB survival intervals');
  const maxTurn = Math.max(...bonuses.map(row => row.slot4));
  const turns = Math.min(stats.turnCount, maxTurn), matches = bonuses.filter(row => turns >= row.slot3 && turns <= row.slot4);
  requireValue(matches.length <= 1, 'Ambiguous original PvB survival interval');
  const turnBonusRate = matches[0]?.value ?? 0, baseScore = stats.totalDamage;
  const turnBonusScore = Math.floor(baseScore * turnBonusRate / 10000), provisionalTotalScore = baseScore + turnBonusScore;
  const finalScore = Math.floor(provisionalTotalScore * original.slot5 / 1000);
  requireValue([turnBonusScore,provisionalTotalScore,finalScore].every(n => Number.isSafeInteger(n) && n >= 0), 'PvB score overflow');
  return { ...stats, baseScore, maxTurn, turnBonusRate, turnBonusScore, provisionalTotalScore,
    difficulty: original.difficulty, difficultyBonusRate: original.slot5, finalScore };
