  if (table === 'UserCharacterFriendshipReward') for (const source of [existing,rows])
    requireValue(source.every(row=>row && Number.isSafeInteger(row.rewardId) && row.rewardId>0) &&
      new Set(source.map(row=>row.rewardId)).size===source.length,'Invalid or duplicate saved CP reward identity');
