    [0,USER_ID].includes(row.userId) && Number.isSafeInteger(row.rewardId) && row.rewardId>0 &&
    friendshipRewardOriginal.get(row.rewardId) && Number.isSafeInteger(row.receivedAt) && row.receivedAt>=0 &&
    typeof row.isReceived==='boolean';
