    const hashInputs = [ids.map(id=>mode===1 ? [id,master.stageProgression[id],master.stages[id].type] :
      [id,master.stageProgression[id],master.stages[id].type,master.stageUnlocks?.[id]]),
      [...episodes].map(([key,id])=>[key,id,id ? master.episodeProgression[id] : null])];
    if ([2,3].includes(mode)) hashInputs.push(master?.communicationCharacters,
      Object.entries(master?.adventureProgression ?? {}).filter(([,row])=>row.type===mode));
