  // deliveries, retaining originals and all reward/operation identities.
  transactionExplorerGiftRepair();
  function transactionExplorerGiftRepair() {
    if (!master?.loginExplorers || !master.items) return;
    const receipts = db.prepare('SELECT * FROM login_explorer_claim ORDER BY received_at').all();
    if (!receipts.length) return;
    const owned = new Map();
    for (const receipt of receipts) {
      const reward = master.loginExplorers[receipt.bonus_id]?.rewards.find(row => row.rank === receipt.rank);
      if (reward) owned.set(receipt.gift_id, { itemId: master.items[reward.rewardKey], amount: reward.amount });
    }
    const repairGift = row => {
      const reward = owned.get(row?.id);
      return reward && row.userId === USER_ID && row.itemId === reward.itemId && row.amount === reward.amount &&
        row.senderType === 0 && row.giftAcquiredType === 0 && row.senderId === 0
        ? { ...row, senderType: 1, giftAcquiredType: 2 } : row;
    };
    const repairBonus = row => row?.userId === USER_ID && row.playableState === 0 && receipts.some(receipt =>
      receipt.bonus_id === row.loginBonusExplorerId && receipt.receipt_count === row.receiptCount &&
      receipt.received_at === row.lastReceivedAt) ? { ...row, playableState: 1 } : row;
    const repairEnvelope = value => {
      if (!value || typeof value !== 'object') return;
      for (const [key, child] of Object.entries(value)) {
        if (key === 'UserGift' && Array.isArray(child)) value[key] = child.map(repairGift);
        else if (key === 'UserLoginBonusExplorer' && Array.isArray(child)) value[key] = child.map(repairBonus);
        else repairEnvelope(child);
      }
    };
    db.exec('BEGIN IMMEDIATE');
    try {
      let changed = false;
      const remember = (kind, key, data) => {
        db.exec(`CREATE TABLE IF NOT EXISTS legacy_explorer_gift_backup (
          kind TEXT NOT NULL, key TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(kind,key))`);
        db.prepare('INSERT OR IGNORE INTO legacy_explorer_gift_backup(kind,key,data) VALUES(?,?,?)').run(kind, String(key), data);
      };
      for (const [name, repair] of [['UserGift',repairGift], ['UserLoginBonusExplorer',repairBonus]]) {
        const row = db.prepare('SELECT data,token FROM profile WHERE name=?').get(name);
        const data = JSON.stringify(JSON.parse(row.data).map(repair));
        if (data === row.data) continue;
        remember('profile', name, JSON.stringify(row));
        db.prepare('UPDATE profile SET data=?,token=? WHERE name=?').run(data, md5(data), name);
        changed = true;
      }
      for (const row of db.prepare('SELECT id,parameters FROM operation_queue WHERE type=2000').all()) {
        const parameters = JSON.parse(row.parameters); repairEnvelope(parameters);
        const data = JSON.stringify(parameters);
        if (data === row.parameters) continue;
        remember('operation', row.id, row.parameters);
        db.prepare('UPDATE operation_queue SET parameters=? WHERE id=?').run(data, row.id);
        changed = true;
      }
      if (changed) {
        for (const row of db.prepare("SELECT key,body FROM reply_cache WHERE content_type='application/json'").all()) {
          const before = Buffer.from(row.body, 'base64').toString('utf8'), response = JSON.parse(before);
          repairEnvelope(response);
          const data = JSON.stringify(response);
          if (data === before) continue;
          remember('reply', row.key, row.body);
          db.prepare('UPDATE reply_cache SET body=? WHERE key=?').run(Buffer.from(data).toString('base64'), row.key);
        }
        // Download replies are read-only and must fetch the repaired metadata.
        db.exec("DELETE FROM reply_cache WHERE action='user_data/pull'");
      }
      db.exec('COMMIT');
    } catch (error) { db.exec('ROLLBACK'); throw error; }
  }
