        if (heroType !== state.userHeroType || level > state.friendshipLv || received.has(id) || issued.has(id)) continue;
        requireValue(Number.isSafeInteger(amount) && amount > 0, 'Invalid original friendship reward');
        let awardedItem = 0;
        if ([0,1,15].includes(type)) { requireValue(itemId > 0, 'Missing original reward item'); awardedItem = itemId; }
        else if (type === 6) awardedItem = master.currencies['currency.valis'];
