      const boughtEquipments = [...equipmentAmounts].map(([equipmentId, amount]) => ({ equipmentId, amount }));
      const boughtCostumes = [...costumeAmounts.keys()];
      let operation = store.operations().find(row => row.type === 9000 && row.parameters.shopProductId === value.shopProductId);
      let rewardOperation;
