        const previousCount = previous && shopPeriod(product.limitType, previous.lastExchangedAt) === period ? previous.count : 0;
        const last = store.db.prepare('SELECT purchase_count count FROM shop_request WHERE product_id=? AND period_key=? ORDER BY purchase_count DESC LIMIT 1')
