          operation = store.issueOperation(10300, value);
          store.db.prepare(`INSERT INTO ability_panel_purchase(operation_id,pc_id,panel_id,job_id,panel_mask,iris_cost)
            VALUES(?,?,?,?,?,?)`).run(operation.id, pcId, value.detailId, jobId, mask, panel.irisCost);
